// Parse OpenAI response safely
const aiRaw = $input.first().json;
const prev   = $('🧹 Validate & Clean Lead Data').first().json;

const rawContent = aiRaw.choices?.[0]?.message?.content
  || aiRaw.message?.content || '{}';

let aiData = {};
try {
  const cleaned = rawContent.replace(/```json|```/g, '').trim();
  aiData = JSON.parse(cleaned);
} catch(e) {
  // Fallback defaults
  aiData = {
    score: 5, scoreLabel: 'warm',
    scoreReason: 'Could not parse AI response',
    tags: ['follow-up-needed'],
    emailSubject: `Following up on your enquiry, ${prev.firstName}`,
    emailBody: `<p>Hi ${prev.firstName},</p><p>Thank you for reaching out! I'd love to discuss how we can help ${prev.company}. Let's schedule a quick call.</p>`,
    calendarCTA: 'Book a 15-minute discovery call'
  };
}

// Validate score range
const score = Math.min(10, Math.max(1, parseInt(aiData.score) || 5));
const scoreLabel = ['hot','warm','cold'].includes(aiData.scoreLabel)
  ? aiData.scoreLabel
  : (score >= 8 ? 'hot' : score >= 5 ? 'warm' : 'cold');

// Add booking link to email body
const calendarLink = process.env.CALENDAR_BOOKING_URL || 'https://calendly.com/yourusername/30min';
const emailBodyWithCal = (aiData.emailBody || '')
  + `\n<p><a href="${calendarLink}" style="background:#2563EB;color:white;padding:10px 20px;border-radius:6px;text-decoration:none;display:inline-block;">📅 ${aiData.calendarCTA || 'Book a Free Discovery Call'}</a></p>`;

return [{
  json: {
    ...prev,
    score,
    scoreLabel,
    scoreReason:  aiData.scoreReason  || '',
    tags:         aiData.tags         || [],
    emailSubject: aiData.emailSubject  || `Reaching out — ${prev.company}`,
    emailBody:    emailBodyWithCal,
    calendarCTA:  aiData.calendarCTA  || 'Book a call',
    aiProcessedAt: new Date().toISOString(),
  }
}];

