const aiRaw = $input.first().json;
const sheetData = $('🔍 Sheets: Check Reply Status').item.json;

const raw = aiRaw.choices?.[0]?.message?.content || '{}';
let parsed = {};
try {
  parsed = JSON.parse(raw.replace(/```json|```/g,'').trim());
} catch(e) {
  parsed = {
    subject: `Quick follow-up — ${sheetData['Company'] || 'your enquiry'}`,
    body: `<p>Hi ${(sheetData['Name'] || 'there').split(' ')[0]},</p><p>Just circling back on my previous email. I'd love to find 15 minutes to chat about how we can help ${sheetData['Company']}.</p>`
  };
}

const calendarLink = process.env.CALENDAR_BOOKING_URL || 'https://calendly.com/yourusername/30min';
parsed.body += `<p><a href="${calendarLink}" style="background:#2563EB;color:white;padding:8px 16px;border-radius:4px;text-decoration:none;">📅 Book a Quick 15-min Call</a></p>`;

return [{
  json: {
    email:        sheetData['Email'],
    name:         sheetData['Name'],
    company:      sheetData['Company'],
    fu1Subject:   parsed.subject,
    fu1Body:      parsed.body,
    followUpNum:  1,
  }
}];

const aiRaw = $input.first().json;
const sheetData = $('🔍 Sheets: Check Reply (Pre FU2)').item.json;

const raw = aiRaw.choices?.[0]?.message?.content || '{}';
let parsed = {};
try {
  parsed = JSON.parse(raw.replace(/```json|```/g,'').trim());
} catch(e) {
  const firstName = (sheetData['Name'] || 'there').split(' ')[0];
  parsed = {
    subject: `Closing the loop, ${firstName}`,
    body: `<p>Hi ${firstName},</p><p>I'll wrap up my outreach here — I know timing isn't always right. If ${sheetData['Company']} ever needs help with automation, I'm just an email away. Wishing you all the best!</p>`
  };
}

return [{
  json: {
    email:       sheetData['Email'],
    fu2Subject:  parsed.subject,
    fu2Body:     parsed.body,
    followUpNum: 2,
  }
}];

const err = $input.first().json;
const msg  = (err.execution?.error?.message || '').toLowerCase();
const node = err.execution?.lastNodeExecuted || 'unknown';

let errorType = 'GENERAL_ERROR';
let severity  = 'HIGH';
let fix = 'Check n8n execution logs.';

if (msg.includes('validation') || msg.includes('invalid')) {
  errorType = 'VALIDATION_ERROR'; severity = 'LOW';
  fix = 'Bad lead data submitted. Check form validation on website.';
} else if (msg.includes('openai') || msg.includes('429') || msg.includes('quota')) {
  errorType = 'OPENAI_QUOTA'; severity = 'MEDIUM';
  fix = 'OpenAI rate limit or quota exceeded. Check API key balance.';
} else if (msg.includes('sheets') || node.includes('Sheets')) {
  errorType = 'SHEETS_ERROR'; severity = 'HIGH';
  fix = 'Google Sheets API error. Check OAuth credentials and sheet ID.';
} else if (msg.includes('gmail') || node.includes('Gmail')) {
  errorType = 'EMAIL_SEND_FAILURE'; severity = 'HIGH';
  fix = 'Gmail OAuth credential expired. Refresh in n8n Credentials.';
} else if (msg.includes('telegram')) {
  errorType = 'NOTIFICATION_FAILURE'; severity = 'LOW';
  fix = 'Telegram bot error. Check bot token and chat ID.';
}

return [{
  json: {
    timestamp:    new Date().toISOString(),
    executionId:  err.execution?.id,
    failedNode:   node,
    errorType, errorMessage: err.execution?.error?.message,
    severity, fix,
    workflowName: err.workflow?.name,
  }
}];
